import pathlib,re

def casefold_collisions(paths):
    groups={}
    for raw in paths:
        if not isinstance(raw,str) or not raw or "\x00" in raw:raise ValueError("invalid path")
        path=raw.replace("\\","/")
        if path.startswith("/") or re.match(r"^[A-Za-z]:",path):raise ValueError("path must be relative")
        parts=path.split("/")
        if any(part in ("",".","..") for part in parts):raise ValueError("unsafe path component")
        normalized="/".join(parts)
        groups.setdefault(normalized.casefold(),set()).add(normalized)
    collisions=[sorted(names) for names in groups.values() if len(names)>1]
    return sorted(collisions,key=lambda group:tuple(x.casefold() for x in group))
